// ---- Template definitions (a template must be defined where it is instantiated) ----
template<class T, class TV1> bool NotEquals(JaggedArray<T> a, TV1 b) { return (!Equals(a, b)); }

template<class T> int32_t RowCount(JaggedArray<T> self) { return (ToCount(Offsets(self)) - 1); }

template<class T> int32_t RowLength(JaggedArray<T> self, int32_t i) { return (At(Offsets(self), (i + 1)) - At(Offsets(self), i)); }

template<class T> Array<T> Row(JaggedArray<T> self, int32_t i) { return SubArray(Values(self), At(Offsets(self), i), RowLength(self, i)); }

template<class T> T RowElement(JaggedArray<T> self, int32_t row, int32_t k) { return At(Values(self), (At(Offsets(self), row) + k)); }

template<class T> bool HasNoRows(JaggedArray<T> self) { return IsZero(RowCount(self)); }

template<class T> bool Equals(JaggedArray<T> a, JaggedArray<T> b) { return a == b; }

template<class TV0> TV0 Multiply(double scalar, TV0 x) { return Multiply(x, scalar); }

template<class TV0> Array<TV0> Repeat(int32_t n, TV0 x) { return MapRange(n, [=](int32_t i) -> TV0 { return x; }); }

template<class TV0, class F0> Array2D<TV0> MakeArray2D(int32_t columns, int32_t rows, F0 f)
{
    Array<TV0> elements = MapRange((columns * rows), [=](int32_t i) -> TV0 { return (f)((i % columns), (i / columns)); });
    return Array2D<TV0>{ elements, columns, rows };
}

template<class TV0, class F0> Array3D<TV0> MakeArray3D(int32_t columns, int32_t rows, int32_t layers, F0 f)
{
    int32_t plane = (columns * rows);
    Array<TV0> elements = MapRange((plane * layers), [=](int32_t i) -> TV0 { return (f)((i % columns), ((i / columns) % rows), (i / plane)); });
    return Array3D<TV0>{ elements, columns, rows, layers };
}

template<class TV0, class TV1, class F0> Array<TV1> MapPairs(Array<TV0> xs, F0 f) { return MapRange((ToCount(xs) / 2), [=](int32_t i) -> TV1 { return (f)(At(xs, (i * 2)), At(xs, ((i * 2) + 1))); }); }

template<class TV0, class TV1, class F0> Array<TV1> MapTriplets(Array<TV0> xs, F0 f) { return MapRange((ToCount(xs) / 3), [=](int32_t i) -> TV1 { return (f)(At(xs, (i * 3)), At(xs, ((i * 3) + 1)), At(xs, ((i * 3) + 2))); }); }

template<class TV0, class TV1, class F0> Array<TV1> MapQuartets(Array<TV0> xs, F0 f) { return MapRange((ToCount(xs) / 4), [=](int32_t i) -> TV1 { return (f)(At(xs, (i * 4)), At(xs, ((i * 4) + 1)), At(xs, ((i * 4) + 2)), At(xs, ((i * 4) + 3))); }); }

template<class TV0> Array<TV0> DropLast(Array<TV0> xs, int32_t n) { return Take(xs, (ToCount(xs) - n)); }

template<class TV0> Array<TV0> TakeLast(Array<TV0> xs, int32_t n) { return MapRange(n, [=](int32_t i) -> TV0 { return At(xs, ((ToCount(xs) - n) + i)); }); }

template<class TV0> Array<TV0> SubArray(Array<TV0> xs, int32_t from, int32_t count) { return MapRange(count, [=](int32_t i) -> TV0 { return At(xs, (from + i)); }); }

template<class TV0> Array<TV0> EveryNth(Array<TV0> self, int32_t n) { return MapRange((((ToCount(self) + n) - 1) / n), [=](int32_t i) -> TV0 { return At(self, (i * n)); }); }

template<class TV0> TV0 AtModulo(Array<TV0> xs, int32_t n) { return At(xs, (n % ToCount(xs))); }

template<class TV0> Array<TV0> SetAt(Array<TV0> self, int32_t index, TV0 value) { return MapRange(ToCount(self), [=](int32_t i) -> TV0 { return ((i == index) ? value : At(self, i)); }); }

template<class TV0, class F0> Array<TV0> Filter(Array<TV0> xs, F0 keep) { return FlatMap(xs, [=](TV0 x) -> Array<TV0> { return ((keep)(x) ? ([&]() -> plato::Array<TV0> { TV0* _lit0 = plato::arena_alloc<TV0>(1); _lit0[0] = x; return plato::make_array(_lit0, 1); }()) : Take(([&]() -> plato::Array<TV0> { TV0* _lit1 = plato::arena_alloc<TV0>(1); _lit1[0] = x; return plato::make_array(_lit1, 1); }()), 0)); }); }

template<class TV0> Array2D<TV0> Slices(Array<TV0> xs, int32_t size)
{
    int32_t rows = (ToCount(xs) / size);
    return Array2D<TV0>{ Take(xs, (rows * size)), size, rows };
}

template<class TV0, class TV1, class TV2, class F0> Array2D<TV2> CartesianProduct(Array<TV0> columns, Array<TV1> rows, F0 func) { return MakeArray2D<TV2>(ToCount(columns), ToCount(rows), [=](int32_t c, int32_t r) -> TV2 { return (func)(At(columns, c), At(rows, r)); }); }

template<class TV0, class F0> Array<int32_t> SortedIndices(Array<TV0> xs, F0 lessOrEqual)
{
    int32_t n = ToCount(xs);
    Buffer<int32_t> src = make_buffer<int32_t>(n);
    int32_t i = 0;
    while (((i <= n) ? (!(i == n)) : false))
    {
        src = Set(src, i, i);
        i = (i + 1);
    }
    Buffer<int32_t> dst = make_buffer<int32_t>(n);
    int32_t width = 1;
    while (((width <= n) ? (!(width == n)) : false))
    {
        int32_t lo = 0;
        while (((lo <= n) ? (!(lo == n)) : false))
        {
            int32_t mid = (((lo + width) <= n) ? (lo + width) : n);
            int32_t hi = ((((lo + width) + width) <= n) ? ((lo + width) + width) : n);
            int32_t a = lo;
            int32_t b = mid;
            int32_t k = lo;
            while (((k <= hi) ? (!(k == hi)) : false))
            {
                if ((mid <= a))
                {
                    dst = Set(dst, k, At(src, b));
                    b = (b + 1);
                }
                else
                {
                    if ((hi <= b))
                    {
                        dst = Set(dst, k, At(src, a));
                        a = (a + 1);
                    }
                    else
                    {
                        if ((lessOrEqual)(At(xs, At(src, a)), At(xs, At(src, b))))
                        {
                            dst = Set(dst, k, At(src, a));
                            a = (a + 1);
                        }
                        else
                        {
                            dst = Set(dst, k, At(src, b));
                            b = (b + 1);
                        }
                    }
                }
                k = (k + 1);
            }
            lo = ((lo + width) + width);
        }
        Buffer<int32_t> merged = dst;
        dst = src;
        src = merged;
        width = (width + width);
    }
    return Freeze(src);
}

template<class TV0, class F0> Array<TV0> Sort(Array<TV0> xs, F0 lessOrEqual) { return Map(SortedIndices(xs, lessOrEqual), [=](int32_t i) -> TV0 { return At(xs, i); }); }

template<class TV0> JaggedArray<TV0> FromRows(Array<Array<TV0>> rows)
{
    Array<int32_t> offsets = MapRange((ToCount(rows) + 1), [=](int32_t i) -> int32_t { return Reduce(MapRange(i, [=](int32_t j) -> int32_t { return ToCount(At(rows, j)); }), 0, [=](int32_t acc, int32_t n) -> int32_t { return (acc + n); }); });
    return JaggedArray<TV0>{ offsets, FlatMap(rows, [=](Array<TV0> r) -> Array<TV0> { return r; }) };
}

template<class T> int32_t LastIndex(Array<T> self) { return (ToCount(self) - 1); }

template<class T> bool IsValidIndex(Array<T> self, int32_t index) { return ((0 <= index) ? (index < ToCount(self)) : false); }

template<class T, class TV2> bool IsValidIndex(Array<T> self, TV2 index) { return ((0 <= Value(index)) ? (Value(index) < ToCount(self)) : false); }

template<class T> T First(Array<T> self) { return At(self, 0); }

template<class T> T Last(Array<T> self) { return At(self, (ToCount(self) - 1)); }

template<class T> T Middle(Array<T> self) { return At(self, (ToCount(self) / 2)); }

template<class T> bool IsEmpty(Array<T> self) { return (ToCount(self) == 0); }

