template<class TV0> TV0 At(Array2D<TV0> self, int32_t column, int32_t row) { return At(self.Elements, ((row * self.ColumnCount) + column)); }

template<class TV0> Array<TV0> Column(Array2D<TV0> self, int32_t col) { return MapRange(self.RowCount, [=](int32_t r) -> TV0 { return At(self, col, r); }); }

template<class TV0> Array<TV0> Row(Array2D<TV0> self, int32_t row) { return MapRange(self.ColumnCount, [=](int32_t c) -> TV0 { return At(self, c, row); }); }

