template <typename F> VectorN MapComponents(VectorN x, F f) { int32_t n = x.Components.count; double* p = arena_alloc<double>(n); for (int32_t i = 0; i < n; i++) p[i] = f(x.Components.data[i]); return VectorN{ make_array(p, n) }; }

template <typename F> VectorN ZipComponents(VectorN a, VectorN b, F f) { int32_t n = a.Components.count < b.Components.count ? a.Components.count : b.Components.count; double* p = arena_alloc<double>(n); for (int32_t i = 0; i < n; i++) p[i] = f(a.Components.data[i], b.Components.data[i]); return VectorN{ make_array(p, n) }; }

template <typename F> VectorN ZipComponents(VectorN a, VectorN b, VectorN c, F f) { int32_t n = a.Components.count; if (b.Components.count < n) n = b.Components.count; if (c.Components.count < n) n = c.Components.count; double* p = arena_alloc<double>(n); for (int32_t i = 0; i < n; i++) p[i] = f(a.Components.data[i], b.Components.data[i], c.Components.data[i]); return VectorN{ make_array(p, n) }; }

template <typename F> bool AllZipComponents(VectorN a, VectorN b, F f) { int32_t n = a.Components.count < b.Components.count ? a.Components.count : b.Components.count; for (int32_t i = 0; i < n; i++) if (!f(a.Components.data[i], b.Components.data[i])) return false; return true; }

template <typename F> bool AllZipComponents(VectorN a, VectorN b, VectorN c, F f) { int32_t n = a.Components.count; if (b.Components.count < n) n = b.Components.count; if (c.Components.count < n) n = c.Components.count; for (int32_t i = 0; i < n; i++) if (!f(a.Components.data[i], b.Components.data[i], c.Components.data[i])) return false; return true; }

template <typename F> bool AnyZipComponents(VectorN a, VectorN b, F f) { int32_t n = a.Components.count < b.Components.count ? a.Components.count : b.Components.count; for (int32_t i = 0; i < n; i++) if (f(a.Components.data[i], b.Components.data[i])) return true; return false; }

template <typename F> bool AllComponents(VectorN x, F f) { for (int32_t i = 0; i < x.Components.count; i++) if (!f(x.Components.data[i])) return false; return true; }

template <typename F> bool AnyComponent(VectorN x, F f) { for (int32_t i = 0; i < x.Components.count; i++) if (f(x.Components.data[i])) return true; return false; }

